using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class ActorInspectorOperations
{
    private readonly ActorImageGeneratorOperations _images=new();private readonly ActorVideoOperations _video=new();
    private static readonly string[] ImageExtensions={"png","jpg","jpeg","webp","bmp","svg","tga","hdr","exr"};
    public void add_image_object_preview(Control owner,Resource data,VBoxContainer parent){var panel=new PanelContainer{Name="ImageObjectPreview"};var style=new StyleBoxFlat{BgColor=new Color("091019"),BorderColor=new Color("355568"),ContentMarginLeft=8,ContentMarginTop=8,ContentMarginRight=8,ContentMarginBottom=8};style.SetBorderWidthAll(1);style.SetCornerRadiusAll(8);panel.AddThemeStyleboxOverride("panel",style);parent.AddChild(panel);var preview=new TextureRect{Name="ImagePreviewTexture",CustomMinimumSize=new Vector2(0,190),ExpandMode=TextureRect.ExpandModeEnum.IgnoreSize,StretchMode=TextureRect.StretchModeEnum.KeepAspectCentered,TextureFilter=CanvasItem.TextureFilterEnum.Nearest,TooltipText="Live preview of the image object"};panel.AddChild(preview);void Update(){preview.Texture=_images.texture_for_object(data);panel.Visible=preview.Texture!=null;}Update();owner.Get("_updaters").AsGodotArray().Add(Callable.From(Update));}
    public void add_image_editor_button(Control owner,VBoxContainer parent,Resource? data){if(data==null||data.Get("type_id").AsString()!="image")return;var source=_data.object_get_value(data,"source","");if(source.VariantType==Variant.Type.Nil||source.VariantType==Variant.Type.String&&source.AsString().Length==0)return;var button=new Button{Text="Edit in Image Editor ↗",TooltipText="Open this image in a dedicated editing tab"};button.Pressed+=()=>open_image_workspace(owner,_data.object_get_value(data,"source",""));parent.AddChild(button);}
    public void open_image_workspace(Control owner,Variant value){if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Resource reference&&ActorDataOperations.ScriptIs(reference,"res://scripts/actors/core/actor_object_reference.gd")){var data=owner.Call("_resolve_object",reference).As<Resource>();if(data==null||data.Get("type_id").AsString()!="image")return;value=_data.object_get_value(data,"source","");}if(value.VariantType==Variant.Type.Nil||value.VariantType==Variant.Type.String&&value.AsString().Length==0)return;owner.GetTree().GetFirstNodeInGroup("actor_scene_tabs")?.Call("open_image",value);}
    public bool inspect_media(Control owner,string path)
    {
        string extension=path.GetExtension().ToLowerInvariant();var video=ActorVideo.extensions();if(!ImageExtensions.Contains(extension)&&!new[]{"wav","mp3","ogg","flac"}.Contains(extension)&&!video.Contains(extension))return false;owner.Set("_inspecting_file",true);owner.Set("_file_selection",Ui<RefCounted>(owner,"model").Get("selected_id"));owner.Set("_actor",default(Variant));owner.Get("_updaters").AsGodotArray().Clear();clear_fields(owner);var fields=Ui<VBoxContainer>(owner,"fields");add_label(fields,path.GetFile());if(ImageExtensions.Contains(extension)){var button=new Button{Text="Edit in Image Editor ↗"};button.Pressed+=()=>open_image_workspace(owner,path);fields.AddChild(button);}var preview=new ActorMediaPreview();preview.Set("path",path);fields.AddChild(preview);return true;
    }
    public void inspect_file_resource(Control owner,string path)
    {
        if(!FileAccess.FileExists(path)||inspect_media(owner,path))return;var data=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Ignore);if(!ActorDataOperations.ScriptIs(data,"res://scripts/actors/core/actor_object_data.gd"))return;string type=data!.Get("type_id").AsString();if(type is "powder_material" or "destruction_material" or "destruction_region" or "debris_vfx")data=ResourceLoader.Load(path,"",ResourceLoader.CacheMode.Replace);if(data==null)return;var registry=Ui<RefCounted>(owner,"registry");var definition=_definitions.get_object_definition(registry,data.Get("type_id").AsStringName());if(definition==null)return;owner.Set("_inspecting_file",true);owner.Set("_file_selection",Ui<RefCounted>(owner,"model").Get("selected_id"));owner.Set("_actor",default(Variant));owner.Get("_updaters").AsGodotArray().Clear();clear_fields(owner);var fields=Ui<VBoxContainer>(owner,"fields");add_label(fields,"RESOURCE PROPERTIES");var title=new Label{Text=path.GetFile()};title.AddThemeFontSizeOverride("font_size",17);fields.AddChild(title);fields.AddChild(new Label{Text=definition.Get("display_name").AsString()+"  •  "+path,Modulate=new Color("819db4"),AutowrapMode=TextServer.AutowrapMode.WordSmart});if(_definitions.object_type_matches(registry,data.Get("type_id").AsStringName(),"image")){add_image_object_preview(owner,data,fields);add_image_editor_button(owner,fields,data);if(data.Get("type_id").AsString()=="image"){prepare_buttons(owner);return;}}string current="";VBoxContainer? group=null;foreach(var value in definition.Get("properties").AsGodotArray()){var property=value.As<Resource>();if(!property_is_visible(owner,property,data))continue;string name=property.Get("options").AsGodotDictionary().GetValueOrDefault("group","Properties").AsString();if(name!=current){current=name;group=stateful_category(owner,current,"FileResource:"+path,fields,"");}add_file_object_value(owner,data,definition,property,group??fields,null);}prepare_buttons(owner);
    }
    public bool actor_reference_candidate(Control owner,Resource property,Resource candidate){var options=property.Get("options").AsGodotDictionary();var types=options.GetValueOrDefault("actor_types",Array.Empty<string>()).AsStringArray();if(types.Length>0&&!types.Contains(candidate.Get("type_id").AsString()))return false;string dimension=options.GetValueOrDefault("actor_dimension","").AsString();if(dimension.Length==0)return true;var definition=_definitions.get_definition(Ui<RefCounted>(owner,"registry"),candidate.Get("type_id").AsStringName());var position=definition!=null?_definitions.find_property(definition,"position"):null;return position!=null&&(dimension=="3d"&&position.Get("value_type").AsInt32()==(int)Variant.Type.Vector3||dimension=="2d"&&position.Get("value_type").AsInt32()==(int)Variant.Type.Vector2);}
    public void add_actor_reference(Control owner,Resource property,Resource definition,VBoxContainer parent){var actor=Ui<Resource>(owner,"_actor");var model=Ui<RefCounted>(owner,"model");var heading=new HBoxContainer();parent.AddChild(heading);heading.AddChild(new Label{Text=property.Get("label").AsString()});var slot=new OptionButton{SizeFlagsHorizontal=Control.SizeFlags.ExpandFill};parent.AddChild(slot);var ids=new List<string>{""};slot.AddItem("<empty>");var create=new Button{Text="+ Create Audio",Visible=false};parent.AddChild(create);bool creates=property.Get("options").AsGodotDictionary().GetValueOrDefault("create_video_audio",false).AsBool();void Update(){ids.Clear();ids.Add("");slot.Clear();slot.AddItem("<empty>");foreach(var value in model.Get("actors").AsGodotArray()){var candidate=value.As<Resource>();if(candidate==actor||!actor_reference_candidate(owner,property,candidate))continue;ids.Add(candidate.Get("id").AsString());slot.AddItem(candidate.Get("display_name").AsString());}int index=ids.IndexOf(actor.Get("values").AsGodotDictionary().GetValueOrDefault(property.Get("id"),"").ToString());slot.Select(Math.Max(0,index));create.Visible=creates&&index<=0;if(creates){var metadata=GD.Load<CSharpScript>("res://scripts/actors/core/ActorVideo.cs").Get("_metadata").AsGodotDictionary();create.Disabled=!_video.info(metadata,actor.Get("values").AsGodotDictionary().GetValueOrDefault("video","").AsString()).GetValueOrDefault("audio",false).AsBool();create.TooltipText=create.Disabled?"This video has no audio track":"Extract a new linked audio child";}}Update();owner.Get("_updaters").AsGodotArray().Add(Callable.From(Update));slot.ItemSelected+=index=>_batch.edit(Ui<RefCounted>(owner,"property_batch"),actor,property.Get("id").AsStringName(),ids[(int)index]);create.Pressed+=()=>_timeline.create_video_audio(model,actor);}
}
